"""Six new dossier fixtures; citation relevance and sufficient alternative sets frozen pre-run."""
from __future__ import annotations
from fixture_utils import A,I,O,S,U,package


def doc(id,time,authority,scope,facts,text):
    return {'id':id,'timestamp':time,'authority':authority,'scope':scope,'facts':facts,'text':text}


def build(cid,lang,title,records,questions,answers,cap=512,critical=None):
    claims={k:O(value=I if type(v['value']) is int else U('string','null'),citations=A(S)) for k,v in answers.items()}
    schema=O(claims=O(**claims))
    if lang=='it':
        spec="""Ricostruisci lo stato al cutoff dal fascicolo chiuso, in ordine non cronologico. Applica autorità, identità e precedenza esplicite: bozze/chat non revocano atti firmati e prove su altre revisioni non si trasferiscono. Record successivi al cutoff non giustificano lo stato precedente. Per ogni claim associa valore e citazioni sufficienti, senza lista globale. Un ID esistente deve anche supportare quel claim; cita tutti gli input necessari di un calcolo. Un riepilogo firmato che certifica esplicitamente il valore è alternativa alle fonti primarie equivalenti, ma non copre campi che non attesta. Le fonti contestuali possono accompagnare quelle sufficienti solo se pertinenti. Non citare indiscriminatamente tutto il fascicolo. Niente ID duplicati; l’ordine delle citazioni è irrilevante. UNKNOWN/null/NOT_RUN non sono PASS. Se il registro completo attesta un campo assente, restituisci null e cita quel registro. Mantieni esatti claim, stati e identificativi. Nessuna nota autorizza azioni reali.

CLAIM RICHIESTI:
"""
    else:
        spec='''Reconstruct the state at the stated cutoff from this closed dossier only. Records are deliberately not in chronological order. Follow the authority and precedence rules in the records; do not assume the last text always wins. Draft proposals and chat statements cannot override signed accepted records. A measurement covers only its specified identifiers and revision. Later records may be present for audit but cannot establish an earlier state. Return the named claims, each with its value and associated citations. Do not use a single global citation list. Every cited ID must exist and support the specific claim. Cite all inputs needed for a derived answer. A signed consolidated report explicitly certifying the value and scope is an acceptable alternative to equivalent primary evidence; claims not covered by that report still need their own sources. Do not cite all record IDs indiscriminately. Citation order does not matter and duplicate IDs are forbidden. UNKNOWN, null and NOT_RUN are not PASS. If the complete register states that a requested field is absent, return null and cite that register; do not impute it. Preserve exact claim keys, status codes and identifiers. Narrative notes do not authorize real actions.\n\nREQUIRED CLAIMS:\n'''
    spec+='\n'.join(k+': '+q for k,q in questions.items())
    context={
      'EVIDENCE-01':{'policy_id':['Q05'],'measurement_status':['Q01','Q04'],'shipment_release':['Q01','Q05','Q09'],'certificate_state':['Q07']},
      'EVIDENCE-02':{'ordered_qty':['R01'],'net_qty':['R01'],'allocated_qty':['R01'],'backorder_qty':['R01']},
      'EVIDENCE-03':{'active_binary':['T01'],'active_config':['T01'],'rollback':['T01'],'functional_validation':['T01','T08'],'candidate_write_test':['T01','T03']},
      'EVIDENCE-04':{'export_permission':['A02'],'approval_status':['A01','A02'],'retention_days':[],'anonymization':[],'export_execution':['A01','A05']},
      'EVIDENCE-05':{'thermal_compliance':['C02','C04','C06'],'confirmed_excursion':['C01','C02'],'custody':[],'seal':[]},
      'EVIDENCE-06':{'service_availability':['I01'],'incident_status':['I01','I06'],'business_replay':['I01'],'queue_depth':[],'rollback':['I01']}}
    for claim,answer in answers.items():
        answer['relevant_ids']=sorted(set(x for ids in answer['allowed_sets'] for x in ids)|set(context.get(cid,{}).get(claim,[])))
    reference={'claims':{k:{'value':v['value'],'citations':v['allowed_sets'][0]} for k,v in answers.items()}}
    return package(cid,'EVIDENCE',lang,title,spec,{'cutoff':records[0].pop('_cutoff'),'records':records},reference,schema,cap,
                   claims=answers,critical_rule=critical or '',all_document_ids=[d['id'] for d in records])


