    r[0]['_cutoff']='2026-01-18T10:15:00Z'
    ans={'thermal_compliance':{'value':'UNKNOWN','allowed_sets':[['C01','C05'],['C08']]},'confirmed_excursion':{'value':'NO','allowed_sets':[['C06','C04'],['C08']]},'custody':{'value':'COMPLETE','allowed_sets':[['C07'],['C08']]},'seal':{'value':'S-880','allowed_sets':[['C07'],['C08']]},'receiver_contact':{'value':None,'allowed_sets':[['C09']]}}
