    ans={'service_availability':{'value':'AVAILABLE','allowed_sets':[['I03'],['I10']]},'incident_status':{'value':'OPEN','allowed_sets':[['I07'],['I10']]},'business_replay':{'value':'FAIL','allowed_sets':[['I06'],['I07'],['I10']]},'queue_depth':{'value':0,'allowed_sets':[['I05'],['I10']]},'rollback':{'value':'NOT_PERFORMED','allowed_sets':[['I07'],['I10']]},'confirmed_root_cause':{'value':None,'allowed_sets':[['I09']]}}
